                "model": MODEL,
                "messages": [{"role": "user", "content": prompt}],
                "options": {"num_predict": 512, "temperature": 0.1},
                "stream": False,
            },
            timeout=timeout,
        )
        response.raise_for_status()
        return response.json()["message"]["content"]
