def _extract_result_payload(result_data: dict[str, Any]) -> Any:
    first_entry = result_data.get("data", [{}])
    if isinstance(first_entry, list) and first_entry:
        first_entry = first_entry[0]
    else:
        first_entry = {}
    return first_entry.get("results", {}).get("c", {})

def _extract_info_circuit(info_data: dict[str, Any]) -> Any:
    items = info_data.get("params", {}).get("quantum_program", {}).get("items", [])
    if not items:
        return {}
    return items[0].get("circuit", {})


def extract_ibm_archive_counts(result_data: dict[str, Any]) -> dict[str, int]:
    """Extract replayable measurement counts from an IBM archive result payload.

    Supported formats:
    - explicit ``counts`` mapping in the payload
    - ``memory`` list of bitstrings
    - ``data`` list of bitstrings or bit rows when dtype is bool

    Encoded binary payloads are intentionally not decoded here because the archive format
    may vary; callers should supply decoded data if available.
    """
    result_payload = _extract_result_payload(result_data)

    counts_payload = result_payload.get("counts")
    if isinstance(counts_payload, dict):
        return {str(key): int(value) for key, value in counts_payload.items()}

    memory_payload = result_payload.get("memory")
    if isinstance(memory_payload, list):
        return _counts_from_memory_rows(memory_payload)

    data_payload = result_payload.get("data")
    if isinstance(data_payload, list):
        return _counts_from_memory_rows(data_payload)

    dtype = result_payload.get("dtype")
    if dtype == "bool" and isinstance(data_payload, str):
        raise ValueError(
            "IBM archive result payload uses encoded boolean data; decoded shot memory or counts are required for replay"
        )

    raise ValueError("IBM archive result payload does not contain replayable counts")


def load_ibm_archive_payloads(
    job_id: str, archive_dir: str | Path | None = None
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Load the raw info/result payload pair for one IBM archive job."""
    resolved_dir = resolve_ibm_archive_dir(archive_dir)
    _validate_job_id(job_id)
    info_path = resolved_dir / f"job-{job_id}-info.json"
    result_path = resolved_dir / f"job-{job_id}-result.json"

    if not info_path.exists() or not result_path.exists():
        raise KeyError(f"Unknown IBM archive job: {job_id}")

    return _load_json(info_path), _load_json(result_path)


def _build_job_summary(
    job_id: str, info_data: dict[str, Any], result_data: dict[str, Any]
) -> IBMArchiveJobSummary:
    circuit_metadata = _extract_info_circuit(info_data)
    result_payload = _extract_result_payload(result_data)
    result_shape = result_payload.get("shape") or []

    # Safely convert shape elements to int, handling malformed data
    try:
        shots = int(result_shape[0]) if len(result_shape) >= 1 else None
    except (ValueError, TypeError):
        shots = None

    try:
        classical_bits = int(result_shape[1]) if len(result_shape) >= 2 else None
    except (ValueError, TypeError):
        classical_bits = None

    # Safely convert full shape array
    safe_shape = []
    for value in result_shape:
        try:
            safe_shape.append(int(value))
        except (ValueError, TypeError):
            safe_shape.append(0)  # Default for unparseable dimensions

    return IBMArchiveJobSummary(
        job_id=job_id,
        backend=info_data.get("backend"),
        created=info_data.get("created"),
        status=info_data.get("state", {}).get("status") or info_data.get("status"),
        program=info_data.get("program"),
        cost=info_data.get("cost"),
        tags=list(info_data.get("tags") or []),
        shots=shots,
        classical_bits=classical_bits,
        qpy_version=circuit_metadata.get("qpy_version"),
        result_schema=result_data.get("schema_version"),
        result_dtype=result_payload.get("dtype"),
        result_shape=safe_shape,
        has_circuit_payload=bool(circuit_metadata.get("circuit_b64")),
    )

"""IBM Quantum archive import helpers for external job/result JSON directories."""

from __future__ import annotations

import json
import os
import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

MAX_IBM_ARCHIVE_JOB_ID_LENGTH = 128


@dataclass
class IBMArchiveJobSummary:
    """Normalized summary for a paired IBM archive job."""

    job_id: str
    backend: str | None
    created: str | None
    status: str | None
    program: str | None
    cost: int | None
    tags: list[str]
    shots: int | None
    classical_bits: int | None
    qpy_version: str | None
    result_schema: str | None
    result_dtype: str | None
    result_shape: list[int]
    has_circuit_payload: bool

    def to_dict(self) -> dict[str, Any]:
        return {
            "job_id": self.job_id,
            "backend": self.backend,
            "created": self.created,
            "status": self.status,
            "program": self.program,
            "cost": self.cost,
            "tags": self.tags,
            "shots": self.shots,
            "classical_bits": self.classical_bits,
            "qpy_version": self.qpy_version,
            "result_schema": self.result_schema,
            "result_dtype": self.result_dtype,
            "result_shape": self.result_shape,
            "has_circuit_payload": self.has_circuit_payload,
        }


@dataclass
class IBMArchiveJobDetail(IBMArchiveJobSummary):
    """Detailed normalized view for a paired IBM archive job."""

    archive_dir: str
    info_file: str
    result_file: str
    notes: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            **super().to_dict(),
            "archive_dir": self.archive_dir,
            "info_file": self.info_file,
            "result_file": self.result_file,
            "notes": self.notes,
        }


def resolve_ibm_archive_dir(archive_dir: str | Path | None = None) -> Path:
    """Resolve archive directory from parameter or environment."""
    candidate = archive_dir or os.environ.get("QPYTH_IBM_ARCHIVE_DIR")
    if not candidate:
        raise ValueError(
            "IBM archive directory is required. Pass archive_dir or set QPYTH_IBM_ARCHIVE_DIR."
        )

    path = Path(candidate).expanduser().resolve()
    if not path.exists() or not path.is_dir():
        raise FileNotFoundError(f"IBM archive directory not found: {path}")

    return path


def _load_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def _counts_from_memory_rows(rows: list[Any]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        if isinstance(row, str):
            bitstring = row.replace(" ", "")
        elif isinstance(row, (list, tuple)):
            try:
                bitstring = "".join("1" if int(value) else "0" for value in row)
            except (TypeError, ValueError) as exc:
                raise ValueError("IBM archive row contains non-binary values") from exc
        else:
            raise ValueError("IBM archive row must be a bitstring or sequence of bits")

        counts[bitstring] = counts.get(bitstring, 0) + 1
    return counts


def _validate_job_id(job_id: str) -> None:
    if len(job_id) > MAX_IBM_ARCHIVE_JOB_ID_LENGTH:
        raise ValueError(
            f"job_id '{job_id}' exceeds {MAX_IBM_ARCHIVE_JOB_ID_LENGTH} characters"
        )

    if not re.fullmatch(r"[A-Za-z0-9](?:[A-Za-z0-9_-]*[A-Za-z0-9])?", job_id):
        raise ValueError(f"job_id '{job_id}' contains invalid characters")


def _extract_job_ids(archive_dir: Path) -> list[str]:
    job_ids = set()
    for path in archive_dir.glob("job-*-info.json"):
        suffix = path.name.removeprefix("job-").removesuffix("-info.json")
        if (archive_dir / f"job-{suffix}-result.json").exists():
            job_ids.add(suffix)
    return sorted(job_ids)

def get_available_ibm_archive_jobs(
    archive_dir: str | Path | None = None,
) -> list[IBMArchiveJobSummary]:
    """List normalized summaries for all paired IBM archive jobs."""
    resolved_dir = resolve_ibm_archive_dir(archive_dir)
    summaries = []
    for job_id in _extract_job_ids(resolved_dir):
        info_data = _load_json(resolved_dir / f"job-{job_id}-info.json")
        result_data = _load_json(resolved_dir / f"job-{job_id}-result.json")
        summaries.append(_build_job_summary(job_id, info_data, result_data))

