    """F = 4(Re(alpha*beta))^2 for X on logical qubit."""
    if error_qubit is None:
        return 1.0
    alpha_c = complex(input_sv[0])
    beta_c = complex(input_sv[1])
    re = np.real(alpha_c.conjugate() * beta_c)
    return float(min(1.0, max(0.0, 4.0 * re * re)))

