@dataclass
class CalibrationTimestamp:
    """
    Timestamp information for calibration data.

    Attributes:
        calibration_time: When the calibration was performed
        last_update: When the data was last updated
        expiry: When the calibration data should be considered stale
        source_file: Original file path if imported from file
    """

    calibration_time: datetime | None = None
    last_update: datetime | None = None
    expiry: datetime | None = None
    source_file: str | None = None

    def to_dict(self) -> dict[str, Any]:
        """Convert to dictionary representation."""
        return {
            "calibration_time": self.calibration_time.isoformat()
            if self.calibration_time
            else None,
            "last_update": self.last_update.isoformat() if self.last_update else None,
            "expiry": self.expiry.isoformat() if self.expiry else None,
            "source_file": self.source_file,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> CalibrationTimestamp:
        """Create from dictionary representation."""
        return cls(
            calibration_time=datetime.fromisoformat(data["calibration_time"])
            if data.get("calibration_time")
            else None,
            last_update=datetime.fromisoformat(data["last_update"])
            if data.get("last_update")
            else None,
            expiry=datetime.fromisoformat(data["expiry"])
            if data.get("expiry")
            else None,
            source_file=data.get("source_file"),
        )


