@app.websocket("/ws/telemetry")
async def websocket_telemetry(websocket: WebSocket):
    """WebSocket endpoint for real-time telemetry."""
    await websocket.accept()
    websocket_clients.append(websocket)

    try:
        while True:
            # Keep connection alive; broadcasting is handled centrally.
            await asyncio.sleep(1.0)
    except WebSocketDisconnect:
        pass
    finally:
        if websocket in websocket_clients:
            websocket_clients.remove(websocket)


def generate_telemetry() -> TelemetryData:
    """Generate simulated telemetry data."""
    jitter = (np.random.random() - 0.5) * 0.02

    return TelemetryData(
        timestamp=datetime.now().timestamp(),
        process_fidelity=current_state.process_fidelity + jitter,
        qber=current_state.qber + abs(jitter) * 0.5,
        noise_factor=current_state.noise_factor + jitter * 0.1,
        channel_delay=current_state.channel_length * 5 + np.random.random() * 2,
    )


async def broadcast_telemetry():
    """Broadcast telemetry to all connected clients."""
    while True:
        if websocket_clients:
            telemetry = generate_telemetry()
            telemetry_buffer.append(telemetry)

            if len(telemetry_buffer) > 100:
                telemetry_buffer.pop(0)

            # Iterate over a snapshot so removals do not skip clients.
            for client in list(websocket_clients):
                try:
                    await client.send_json(telemetry.to_dict())
                except Exception:
                    if client in websocket_clients:
                        websocket_clients.remove(client)

        await asyncio.sleep(1.0)


