        AgentRole.KNOWLEDGE_SYNTHESIZER, AgentRole.SELF_ANALYZER,
        AgentRole.NETWORK_COORDINATOR
    ]
    for role in integration_roles:
        if role in role_groups:
            ensemble_structure['integration_layer'].extend(role_groups[role])

    # Output Layer: Protection/Justice, Process Automators
    output_roles = [
        AgentRole.PROTECTION_JUSTICE, AgentRole.PROCESS_AUTOMATOR,
        AgentRole.CONTINUOUS_MONITOR
    ]
    for role in output_roles:
        if role in role_groups:
            ensemble_structure['output_layer'].extend(role_groups[role])

    # Ensure minimum agents in each layer
    min_agents_per_layer = 1
    for layer_name, layer_agents in ensemble_structure.items():
        if len(layer_agents) < min_agents_per_layer and self.agents:
            # Add highest fitness agents to meet minimum
            sorted_agents = sorted(
                self.agents,
                key=lambda a: a.metrics.fitness,
                reverse=True
            )
            additional = sorted_agents[:min_agents_per_layer - len(layer_agents)]
            ensemble_structure[layer_name].extend(additional)

    return {
        'structure': ensemble_structure,
        'configuration': config,
        'primary_objective': primary_objective,
        'total_agents': len(self.agents),
        'layer_agents': {
            layer: len(agents)
            for layer, agents in ensemble_structure.items()
        }
    }

def calculate_ensemble_consciousness(
    self,
    ensemble_structure: Dict[str, Any],
