import { useState } from 'react';
import { SecurityAudit as SecurityAuditModel } from '../models/quantum';
import { Shield, AlertTriangle, Activity, TrendingUp } from 'lucide-react';

interface SecurityAuditProps {
  audit: SecurityAuditModel;
  isLoading?: boolean;
  onRunAudit: () => void;
}

export const SecurityAudit: React.FC<SecurityAuditProps> = ({
  audit,
  isLoading = false,
  onRunAudit,
}) => {
  const [isAuditing, setIsAuditing] = useState(false);
  const [auditProgress, setAuditProgress] = useState(0);

  const runAudit = () => {
    setIsAuditing(true);
    setAuditProgress(0);
    onRunAudit();

    const interval = setInterval(() => {
      setAuditProgress((prev) => {
        if (prev >= 100) {
          clearInterval(interval);
          setIsAuditing(false);
          return 100;
        }
        return prev + 10;
      });
    }, 200);
  };

  const getScoreColor = (score: number) => {
    if (score >= 80) return '#10b981';
    if (score >= 60) return '#06b6d4';
    if (score >= 40) return '#f59e0b';
    return '#ef4444';
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'LOW':
        return '#10b981';
      case 'MEDIUM':
        return '#06b6d4';
      case 'HIGH':
        return '#f59e0b';
      case 'CRITICAL':
        return '#ef4444';
      default:
        return '#94a3b8';
    }
  };

  const threats = audit.threats.length > 0 ? audit.threats : [];

  return (
    <div className="metric-card rounded-lg p-4 h-full flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Shield className="w-5 h-5 text-quantum-green" />
          <h3 className="text-lg font-semibold text-white">Security Audit</h3>
        </div>
        <button
          onClick={runAudit}
          disabled={isAuditing || isLoading}
          className={`px-3 py-1 rounded text-sm font-medium transition-colors ${
            isAuditing || isLoading
              ? 'bg-slate-700 text-slate-400 cursor-not-allowed'
              : 'bg-quantum-green text-white hover:bg-green-600'
          }`}
        >
          {isAuditing || isLoading ? 'Auditing...' : 'Run Audit'}
        </button>
      </div>

      {(isAuditing || isLoading) && (
        <div className="mb-4">
          <div className="h-2 bg-slate-700 rounded-full overflow-hidden">
            <div
              className="h-full bg-quantum-cyan transition-all duration-200"
              style={{ width: `${isLoading ? 100 : auditProgress}%` }}
            />
          </div>
          <div className="text-xs text-slate-400 mt-1">
            Analyzing threat vectors... {isLoading ? 100 : auditProgress}%
          </div>
        </div>
      )}

      <div className="grid grid-cols-3 gap-3 mb-4">
        <div className="bg-slate-800 rounded p-3 text-center">
          <div className="text-xs text-slate-400 mb-1">Score</div>
          <div className="text-2xl font-bold" style={{ color: getScoreColor(audit.overallScore) }}>
            {Math.round(audit.overallScore)}%
          </div>
        </div>
        <div className="bg-slate-800 rounded p-3 text-center">
          <div className="text-xs text-slate-400 mb-1">State</div>
          <div className="text-lg font-bold" style={{ color: getScoreColor(audit.overallScore) }}>
            {audit.state}
          </div>
        </div>
        <div className="bg-slate-800 rounded p-3 text-center">
          <div className="text-xs text-slate-400 mb-1">Confidence</div>
          <div className="text-lg font-bold text-quantum-cyan">
            {Math.round(audit.antiAttackConfidence || 0)}%
          </div>
        </div>
      </div>

