// ICOSAHEDRON NODE CLASS
// ═══════════════════════════════════════════════════════════════
class IcosahedronNode {
    constructor(agent, position, index) {
        this.agent = agent;
        this.basePosition = position.clone();
        this.index = index;
        this.phase = agent.phi;
        this.time = Math.random() * 1000;

        // Icosahedron geometry
        const radius = 2.0;
        this.geometry = new THREE.IcosahedronGeometry(radius, 0);

        // Store original vertices
        const posAttr = this.geometry.attributes.position;
        this.baseVertices = [];
        for (let i = 0; i < posAttr.count; i++) {
            this.baseVertices.push(new THREE.Vector3().fromBufferAttribute(posAttr, i));
        }

        // Materials: solid core + wireframe
        const color = new THREE.Color(agent.color);
        this.solidMat = new THREE.MeshBasicMaterial({
            color: color,
            transparent: true,
            opacity: 0.25
        });
        this.wireMat = new THREE.MeshBasicMaterial({
            color: agent.color,
            wireframe: true
        });

        // Glow sprite
        this.createGlow(agent.color);
    }

    createGlow(color) {
        const spriteMat = new THREE.SpriteMaterial({
            map: this.createGlowTexture(),
            color: color,
            transparent: true,
            blending: THREE.AdditiveBlending,
        });
        this.glow = new THREE.Sprite(spriteMat);
        this.glow.scale.set(8, 8, 1);
        this.mesh.add(this.glow);
    }

    createGlowTexture() {
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 64;
        const ctx = canvas.getContext('2d');
        const gradient = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
        gradient.addColorStop(0, 'rgba(255,255,255,1)');
        gradient.addColorStop(0.3, 'rgba(255,255,255,0.8)');
        gradient.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, 64, 64);
        const texture = new THREE.CanvasTexture(canvas);
        return texture;
    }

    update(networkPhase, time) {
        this.time = time;
        const deviation = Math.abs(networkPhase - PHI);

        // Fidelity calculation
        const maxDev = 1.618;
        this.fidelity = Math.max(0, 100 - (deviation / maxDev) * 150);
        if (deviation < 0.05) this.fidelity = 100;

        // Vertex jitter based on deviation from φ
        const positions = this.geometry.attributes.position;
        const jitterAmount = deviation * 0.25;

        for (let i = 0; i < positions.count; i++) {
            const base = this.baseVertices[i];
            const noiseX = (Math.random() - 0.5) * jitterAmount;
            const noiseY = (Math.random() - 0.5) * jitterAmount;
            const noiseZ = (Math.random() - 0.5) * jitterAmount;

            // Harmonic pulse when at φ
            const harmonic = this.fidelity >= 99 ? Math.sin(time * 0.003 + base.y) * 0.04 : 0;

            positions.setXYZ(i, base.x + noiseX + harmonic, base.y + noiseY + harmonic, base.z + noiseZ + harmonic);
        }
        positions.needsUpdate = true;

        // Opacity based on fidelity
        this.solidMat.opacity = 0.15 + (this.fidelity / 100) * 0.35;
        this.wireMat.opacity = 0.3 + (this.fidelity / 100) * 0.7;
        this.wireMat.transparent = true;

        // Glow intensity
        this.glow.material.opacity = 0.15 + (this.fidelity / 100) * 0.5;

        // Rotation
        this.mesh.rotation.x += 0.003 * (this.fidelity / 100);
        this.mesh.rotation.y += 0.006 * (this.fidelity / 100);

        // Floating motion
        this.mesh.position.y = this.basePosition.y + Math.sin(time * 0.001 + this.index) * 0.3;
    }
}

// ═══════════════════════════════════════════════════════════════
// CONNECTION LINES (Sierpinski entanglement)
// ═══════════════════════════════════════════════════════════════
function buildConnections(nodes, depth) {
    // Clear old lines
    const oldLines = scene.children.filter(c => c.userData.isConnectionLine);
    oldLines.forEach(l => scene.remove(l));

this.mesh = new THREE.Mesh(this.geometry, this.solidMat);
this.wireframe = new THREE.Mesh(this.geometry, this.wireMat);
this.mesh.add(this.wireframe);
this.mesh.position.copy(position);

if (depth === 1) {
    // Connect triangle: 0-1, 1-2, 2-0
    createLine(nodes[0].mesh.position, nodes[1].mesh.position);
    createLine(nodes[1].mesh.position, nodes[2].mesh.position);
    createLine(nodes[2].mesh.position, nodes[0].mesh.position);
} else {
    // Sierpinski pattern: connect in groups of 3
    const nodesPerGroup = 3;
    const groups = Math.pow(3, depth - 1);
    const nodesPerSubGroup = Math.pow(3, depth - 1);

        for (let g = 0; g < groups; g++) {
            const baseIdx = g * nodesPerGroup;
            if (baseIdx + 2 < nodes.length) {
                // Inner triangle
                createLine(nodes[baseIdx].mesh.position, nodes[baseIdx + 1].mesh.position);
                createLine(nodes[baseIdx + 1].mesh.position, nodes[baseIdx + 2].mesh.position);
                createLine(nodes[baseIdx + 2].mesh.position, nodes[baseIdx].mesh.position);
            }
            // Cross connections between groups at same level
            if (g > 0 && (g % 3 !== 0 || depth > 2)) {
                const prevBase = (g - 1) * nodesPerGroup;
                if (prevBase + 1 < nodes.length) {
                    createLine(nodes[baseIdx].mesh.position, nodes[prevBase].mesh.position);
                }
            }
        }
    }
}

function createLine(posA, posB) {
    const points = [posA.clone(), posB.clone()];
    const geometry = new THREE.BufferGeometry().setFromPoints(points);
    const material = new THREE.LineBasicMaterial({
        color: 0x00ffcc,
        transparent: true,
        opacity: 0.15,
        blending: THREE.AdditiveBlending
    });
    const line = new THREE.Line(geometry, material);
    line.userData.isConnectionLine = true;
    scene.add(line);
}

