// BUILD NETWORK
// ═══════════════════════════════════════════════════════════════
let nodes = [];
let currentDepth = 2;

function buildNetwork(depth) {
    // Remove old nodes
    nodes.forEach(n => scene.remove(n.mesh));
    nodes = [];

    const positions = sierpinskiPositions(depth);
    const nodeCount = Math.min(positions.length, AGENTS.length);

    for (let i = 0; i < nodeCount; i++) {
        const node = new IcosahedronNode(AGENTS[i], positions[i], i);
        nodes.push(node);
        scene.add(node.mesh);
    }

    buildConnections(nodes, depth);
    updateAgentList();

    document.getElementById('nodeCount').textContent = nodeCount;
}

function updateAgentList() {
    const list = document.getElementById('agentList');
    list.innerHTML = '';
    nodes.forEach((node, i) => {
        const item = document.createElement('div');
        item.className = 'agent-item';
