        )
    )
    validations.append(self._validate_optimization_log())

from __future__ import annotations

import json
from pathlib import Path
from statistics import mean
from typing import Any

from pydantic import ValidationError

from .models import (
    AgentDNA,
    AgentMemory,
    EvalDataset,
    GeometryConfig,
    OptimizationEntry,
    SummarySnapshot,
    ValidationResult,
    VaultConfig,
