def _clean_bitstring(bitstring: str) -> str:
    """Normalize Qiskit count keys by removing register separators."""
    return bitstring.replace(" ", "")


def normalize_counts(counts: Mapping[str, int]) -> dict[str, float]:
    """Convert a counts dictionary into a normalized probability distribution."""
    total = sum(max(0, int(value)) for value in counts.values())
    if total <= 0:
        return {}

    distribution: dict[str, float] = {}
    for bitstring, value in counts.items():
        normalized_value = max(0, int(value))
        if normalized_value <= 0:
            continue
        cleaned = _clean_bitstring(bitstring)
        distribution[cleaned] = distribution.get(cleaned, 0.0) + (
            normalized_value / total
        )

    return distribution


def _union_probabilities(
    counts_a: Mapping[str, int], counts_b: Mapping[str, int]
) -> tuple[dict[str, float], dict[str, float], set[str]]:
    dist_a = normalize_counts(counts_a)
    dist_b = normalize_counts(counts_b)
    keys = set(dist_a) | set(dist_b)
    return dist_a, dist_b, keys


def total_variation_distance(
    counts_a: Mapping[str, int], counts_b: Mapping[str, int]
) -> float:
    """Compute total variation distance between two count distributions."""
    dist_a, dist_b, keys = _union_probabilities(counts_a, counts_b)
    return 0.5 * sum(abs(dist_a.get(key, 0.0) - dist_b.get(key, 0.0)) for key in keys)


def hellinger_distance(
    counts_a: Mapping[str, int], counts_b: Mapping[str, int]
) -> float:
    """Compute Hellinger distance between two count distributions."""
    dist_a, dist_b, keys = _union_probabilities(counts_a, counts_b)
    squared = sum(
        (math.sqrt(dist_a.get(key, 0.0)) - math.sqrt(dist_b.get(key, 0.0))) ** 2
        for key in keys
    )
    return math.sqrt(squared) / math.sqrt(2.0)


def jensen_shannon_divergence(
    counts_a: Mapping[str, int], counts_b: Mapping[str, int]
) -> float:
    """Compute Jensen-Shannon divergence in bits between two distributions."""
    dist_a, dist_b, keys = _union_probabilities(counts_a, counts_b)
    midpoint = {
        key: 0.5 * (dist_a.get(key, 0.0) + dist_b.get(key, 0.0)) for key in keys
    }

    def _kl_divergence(left: dict[str, float], right: dict[str, float]) -> float:
        divergence = 0.0
        for key in keys:
            left_value = left.get(key, 0.0)
            right_value = right.get(key, 0.0)
            if left_value > 0 and right_value > 0:
                divergence += left_value * math.log2(left_value / right_value)
        return divergence

    return 0.5 * _kl_divergence(dist_a, midpoint) + 0.5 * _kl_divergence(
        dist_b, midpoint
    )


def expectation_value_z(counts: Mapping[str, int], qubit_index: int = 0) -> float:
    """Estimate the expectation value of Z for one measured qubit from counts.

    The qubit index is interpreted in Qiskit order, where qubit 0 is the rightmost bit
    in the measurement string.
    """
    distribution = normalize_counts(counts)
    if not distribution:
        return 0.0

    exp_value = 0.0
    for bitstring, probability in distribution.items():
        if qubit_index >= len(bitstring):
            raise ValueError(
                f"Qubit index {qubit_index} is out of range for bitstring '{bitstring}'"
            )
        measured_bit = bitstring[-(qubit_index + 1)]
        exp_value += probability if measured_bit == "0" else -probability
    return exp_value

