            "n": n,
            "min": vals[0],
            "p25": _pct(0.25),
            "median": _pct(0.50),
            "p75": _pct(0.75),
            "p95": _pct(0.95),
            "max": vals[-1],
            "mean": round(sum(vals) / n, 1),
        }

def _hash_file(path: Path) -> str:
    import hashlib
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()

