def _serialize_circuit(circuit: QuantumCircuit) -> str:
    try:
        from qiskit.qasm2 import dumps as qasm2_dumps  # type: ignore

        return qasm2_dumps(circuit)  # type: ignore[no-any-return]
    except Exception:
        return repr(circuit)


def _hash_circuit(circuit: QuantumCircuit) -> str:
    payload = _serialize_circuit(circuit).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _coerce_counts(result: Any) -> dict[str, int]:
    if isinstance(result, dict):
        return {str(key): int(value) for key, value in result.items()}
    if hasattr(result, "counts"):
        counts = result.counts
        if isinstance(counts, dict):
            return {str(key): int(value) for key, value in counts.items()}
    raise TypeError(
        "Executor result must be a counts dict or expose a 'counts' attribute"
    )


def _transpile_shared(
    circuit: QuantumCircuit,
    config: ValidationRunConfig,
    backend: Any | None = None,
    transpiler: Transpiler | None = None,
) -> QuantumCircuit:
    transpile_fn = transpiler or transpile
    kwargs: dict[str, Any] = {"optimization_level": config.optimization_level}
    if backend is not None:
        kwargs["backend"] = backend
    elif config.basis_gates:
        kwargs["basis_gates"] = config.basis_gates
        if config.coupling_map:
            kwargs["coupling_map"] = config.coupling_map
    return transpile_fn(circuit, **kwargs)


def run_benchmark_case(
    benchmark: BenchmarkCase,
    simulation_executor: Executor,
    hardware_executor: Executor,
    config: ValidationRunConfig,
    *,
    backend: Any | None = None,
    transpiler: Transpiler | None = None,
    now_fn: Callable[[], str] = utc_now_iso,
) -> ValidationRecord:
    """Run one benchmark through a shared transpilation pipeline and score agreement."""
    logical_hash = _hash_circuit(benchmark.circuit)
    transpiled_circuit = _transpile_shared(
        benchmark.circuit, config, backend, transpiler
    )
    transpiled_hash = _hash_circuit(transpiled_circuit)

