export const PyramidVisualization: React.FC<PyramidVisualizationProps> = ({
  selectedLayer,
  onLayerSelect,
}) => {
  const layerHeight = 80;
  const baseWidth = 500;
  const topWidth = 150;
  const widthStep = (baseWidth - topWidth) / (PYRAMID_LAYERS.length - 1);

  return (
    <div className="relative flex flex-col items-center justify-center h-full">
      <svg
        viewBox="0 0 600 520"
        className="w-full max-w-2xl"
        style={{ filter: 'drop-shadow(0 0 20px rgba(14, 165, 233, 0.3))' }}
      >
        <defs>
          {PYRAMID_LAYERS.map((layer) => (
            <linearGradient
              key={`gradient-${layer.id}`}
              id={`gradient-${layer.id}`}
              x1="0%"
              y1="0%"
              x2="100%"
              y2="0%"
            >
              <stop
                offset="0%"
                stopColor={layer.color}
                stopOpacity={selectedLayer === layer.id ? 1 : 0.7}
              />
              <stop
                offset="50%"
                stopColor={layer.color}
                stopOpacity={selectedLayer === layer.id ? 0.9 : 0.6}
              />
              <stop
                offset="100%"
                stopColor={layer.color}
                stopOpacity={selectedLayer === layer.id ? 1 : 0.7}
              />
            </linearGradient>
          ))}
        </defs>

        {PYRAMID_LAYERS.map((layer, index) => {
          const y = index * layerHeight + 20;
          const currentWidth = baseWidth - index * widthStep;
          const nextWidth = baseWidth - (index + 1) * widthStep;
          const xOffset = (600 - currentWidth) / 2;
          const nextXOffset = (600 - nextWidth) / 2;

          const points = [
            `${xOffset},${y}`,
            `${xOffset + currentWidth},${y}`,
            `${nextXOffset + nextWidth},${y + layerHeight}`,
            `${nextXOffset},${y + layerHeight}`,
          ].join(' ');

          const isSelected = selectedLayer === layer.id;

          return (
            <g key={layer.id}>
