def query(self, text: str, k: int = 5) -> List[dict]:
        if not self.available or not text:
            return []
        qv = _embed([text])
        if qv is None:
            return []
        # cosine == dot product (both L2-normalized)
        sims = self.embeddings @ qv[0]
        order = _np.argsort(-sims)[:k]
        out: List[dict] = []
        for i in order:
            s = float(sims[i])
            if s <= 0:
                continue
            d = self.docs[int(i)]
            out.append({
                "id": d["id"], "score": round(s, 4),
