.mini-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 14px;
    font-size: 0.92rem;
}

.mini-table td,
.mini-table th {
    padding: 8px 10px;
    border-bottom: 1px solid #2a2a3a;
    text-align: left;
}

.mini-table tr:last-child td,
.mini-table tr:last-child th {
    border-bottom: none;
}

.callout {
    background: rgba(18, 18, 26, 0.92);
    border-left: 4px solid var(--accent);
    border-radius: 8px;
    padding: 16px 18px;
    margin: 18px 0;
}

.pill-row {
    display: flex;
    flex-wrap: wrap;
