export interface PyramidLayer {
  id: number;
  name: string;
  description: string;
  color: string;
  metrics: LayerMetrics;
  vulnerabilities: string[];
  safeguards: string[];
}

export interface LayerMetrics {
  fidelity: number;
  qber: number;
  noiseFactor: number;
  errorRate: number;
}

export interface QuantumState {
  processFidelity: number;
  goalFidelity: number;
  baselineRange: [number, number];
  qber: number;
  darkCountRate: number;
  channelLength: number;
  ddLoops: number;
  noiseFactor: number;
  tomographyStates: number;
  keyExchangeTimeout: number;
  targetTimeout: number;
}

export interface CalibrationSettings {
  ddLoops: number;
  noiseFactor: number;
  tomographyRate: number;
  timeoutPolicy: number;
  dynamicBranchesEnabled: boolean;
}

export interface SecurityAudit {
  overallScore: number;
  state: 'SECURE' | 'WARNING' | 'CRITICAL';
  antiAttackConfidence: number;
  threats: ThreatVector[];
  lastAudit: Date;
}

export interface ThreatVector {
  id: string;
  name: string;
  severity: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  description: string;
  mitigation: string;
}

export interface TelemetryData {
  timestamp: number;
  processFidelity: number;
  qber: number;
  noiseFactor: number;
  channelDelay: number;
}
